from html.parser import HTMLParser

class TitleFinder(HTMLParser):
    def __init__(self):
        super().__init__()
        self.inside = False
        self.title = ''
    def handle_starttag(self, tag, attrs):
        if tag == 'title':
            self.inside = True
    def handle_endtag(self, tag):
        if tag == 'title':
            self.inside = False
    def handle_data(self, data):
        if self.inside:
            self.title += data

p = TitleFinder()
p.feed('<html><head><title>Kitap Listesi</title></head></html>')
print(p.title)

