from html.parser import HTMLParser

class LinkFinder(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []
    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            href = dict(attrs).get('href')
            if href:
                self.links.append(href)

p = LinkFinder()
p.feed('<a href="/urun/1">Bir</a><a>Bos</a><a href="/urun/2">Iki</a>')
print(p.links)

from html.parser import HTMLParser

class BookFinder(HTMLParser):
    def __init__(self):
        super().__init__()
        self.want = False
        self.books = []
    def handle_starttag(self, tag, attrs):
        self.want = (tag == 'li' and dict(attrs).get('class') == 'book')
    def handle_data(self, data):
        if self.want:
            self.books.append(data)
            self.want = False

p = BookFinder()
p.feed('<ul><li class="book">Sefiller</li><li class="ad">Reklam</li><li class="book">Suc ve Ceza</li></ul>')
print(p.books)

from html.parser import HTMLParser

class Rows(HTMLParser):
    def __init__(self):
        super().__init__()
        self.cells, self.rows = [], []
    def handle_data(self, data):
        if data.strip():
            self.cells.append(data.strip())
    def handle_endtag(self, tag):
        if tag == 'tr' and self.cells:
            self.rows.append({'ad': self.cells[0], 'fiyat': self.cells[1]})
            self.cells = []

p = Rows()
p.feed('<table><tr><td>Kalem</td><td>12.50</td></tr><tr><td>Defter</td><td>30.00</td></tr></table>')
print(p.rows)

